import type { DifferentialPair, SimpleRouteConnection } from "../types"
import type { LengthMatchingConfig } from "./internal-types"
import type { LengthMatchingSolverParams } from "./types"

/** Validate public options once and resolve defaults for every internal module. */
export const validateAndResolveParams = (
  params: LengthMatchingSolverParams,
): LengthMatchingConfig => {
  const maximumMeanderDepth = params.maximumMeanderDepth ?? 5
  const maxToothCount = params.maxToothCount ?? 12
  if (!Number.isFinite(maximumMeanderDepth) || maximumMeanderDepth <= 0) {
    throw new Error(
      "LengthMatchingSolver: maximumMeanderDepth must be a positive finite number",
    )
  }
  if (
    params.minimumToothPitch !== undefined &&
    (!Number.isFinite(params.minimumToothPitch) ||
      params.minimumToothPitch <= 0)
  ) {
    throw new Error(
      "LengthMatchingSolver: minimumToothPitch must be a positive finite number",
    )
  }
  if (
    params.minMeanderGap !== undefined &&
    (!Number.isFinite(params.minMeanderGap) || params.minMeanderGap <= 0)
  ) {
    throw new Error(
      "LengthMatchingSolver: minMeanderGap must be a positive finite number",
    )
  }
  if (
    params.minMeanderHeight !== undefined &&
    (!Number.isFinite(params.minMeanderHeight) || params.minMeanderHeight <= 0)
  ) {
    throw new Error(
      "LengthMatchingSolver: minMeanderHeight must be a positive finite number",
    )
  }
  if (
    params.minMeanderHeight !== undefined &&
    params.minMeanderHeight > maximumMeanderDepth
  ) {
    throw new Error(
      "LengthMatchingSolver: minMeanderHeight cannot exceed maximumMeanderDepth",
    )
  }
  if (
    !Number.isFinite(maxToothCount) ||
    !Number.isInteger(maxToothCount) ||
    maxToothCount <= 0
  ) {
    throw new Error(
      "LengthMatchingSolver: maxToothCount must be a positive finite integer",
    )
  }
  return {
    maximumMeanderDepth,
    minimumToothPitch: params.minimumToothPitch,
    minMeanderGap: params.minMeanderGap,
    minMeanderHeight: params.minMeanderHeight,
    maxToothCount,
    obstacles: params.obstacles ?? [],
    bounds: params.bounds,
    obstacleMargin: params.obstacleMargin ?? 0.15,
    layerCount: params.layerCount ?? 2,
    colorMap: params.colorMap ?? {},
  }
}

/** Fail early when a pair cannot refer to two routable source connections. */
export const validatePair = (
  pair: DifferentialPair,
  originalConnections: SimpleRouteConnection[],
): void => {
  if (pair.connectionNames[0] === pair.connectionNames[1]) {
    throw new Error(
      "LengthMatchingSolver: a differential pair must reference two distinct connections",
    )
  }
  if (!Number.isFinite(pair.lengthTolerance) || pair.lengthTolerance < 0) {
    throw new Error(
      "LengthMatchingSolver: differential pair lengthTolerance must be a non-negative finite number",
    )
  }
  const connectionsByName = new Map(
    originalConnections.map((connection) => [connection.name, connection]),
  )
  for (const connectionName of pair.connectionNames) {
    const connection = connectionsByName.get(connectionName)
    if (!connection)
      throw new Error(
        `LengthMatchingSolver: differential pair references unknown connection "${connectionName}"`,
      )
    if (connection.pointsToConnect.length !== 2) {
      throw new Error(
        `LengthMatchingSolver: differential pair connection "${connectionName}" must have exactly two points before MST splitting`,
      )
    }
  }
}
import { getRouteLength } from "../route-geometry"
import type { HighDensityRoute } from "../types"

export const getLogicalConnectionName = (route: HighDensityRoute): string =>
  route.rootConnectionName ?? route.connectionName

/** Find each routed branch that belongs to one logical connection. */
export const findConnectionRouteIndexes = (
  routes: HighDensityRoute[],
  connectionName: string,
): number[] =>
  routes.flatMap((route, index) =>
    getLogicalConnectionName(route) === connectionName ? [index] : [],
  )

/** Sum every routed branch belonging to a logical connection. */
export const getConnectionLength = (
  routes: HighDensityRoute[],
  routeIndexes: number[],
): number =>
  routeIndexes.reduce(
    (total, routeIndex) => total + getRouteLength(routes[routeIndex]!),
    0,
  )
import { getMinimumSegmentDistance } from "../route-geometry"
import type { HighDensityRoute, Obstacle, RoutePoint } from "../types"
import { getLogicalConnectionName } from "./connection-routes"

const isObstacleOnLayer = (
  obstacle: Obstacle,
  z: number,
  layerCount: number,
): boolean => {
  if (obstacle.zLayers) return obstacle.zLayers.includes(z)
  return obstacle.layers.some(
    (layer) =>
      (layer === "top" && z === 0) ||
      (layer === "bottom" && z === layerCount - 1) ||
      layer === `inner${z}`,
  )
}

const segmentTouchesInflatedObstacle = (
  start: RoutePoint,
  end: RoutePoint,
  obstacle: Obstacle,
  margin: number,
): boolean => {
  const minX = obstacle.center.x - obstacle.width / 2 - margin
  const maxX = obstacle.center.x + obstacle.width / 2 + margin
  const minY = obstacle.center.y - obstacle.height / 2 - margin
  const maxY = obstacle.center.y + obstacle.height / 2 + margin
  if (
    (start.x >= minX &&
      start.x <= maxX &&
      start.y >= minY &&
      start.y <= maxY) ||
    (end.x >= minX && end.x <= maxX && end.y >= minY && end.y <= maxY)
  )
    return true
  const corners = [
    { x: minX, y: minY },
    { x: maxX, y: minY },
    { x: maxX, y: maxY },
    { x: minX, y: maxY },
  ]
  return corners.some(
    (corner, index) =>
      getMinimumSegmentDistance(
        start,
        end,
        corner,
        corners[(index + 1) % corners.length]!,
      ) === 0,
  )
}

/** Check candidate bounds, obstacle clearance, and clearance from other connections. */
export const isCandidateGeometryValid = (input: {
  route: HighDensityRoute
  meanderPoints: RoutePoint[]
  routedRoutes: HighDensityRoute[]
  obstacles: Obstacle[]
  bounds?: { minX: number; maxX: number; minY: number; maxY: number }
  layerCount: number
  obstacleMargin: number
}): boolean => {
  if (
    input.bounds &&
    input.meanderPoints.some(
      (point) =>
        point.x < input.bounds!.minX ||
        point.x > input.bounds!.maxX ||
        point.y < input.bounds!.minY ||
        point.y > input.bounds!.maxY,
    )
  )
    return false
  const connectionName = getLogicalConnectionName(input.route)
  const obstacleMargin = input.route.traceThickness / 2 + input.obstacleMargin
  for (let index = 0; index < input.meanderPoints.length - 1; index++) {
    const start = input.meanderPoints[index]!
    const end = input.meanderPoints[index + 1]!
    for (const obstacle of input.obstacles) {
      if (!isObstacleOnLayer(obstacle, start.z, input.layerCount)) continue
      const isTerminalLead =
        index === 0 || index === input.meanderPoints.length - 2
      if (obstacle.connectedTo.includes(connectionName) && isTerminalLead)
        continue
      if (segmentTouchesInflatedObstacle(start, end, obstacle, obstacleMargin))
        return false
    }
    for (const otherRoute of input.routedRoutes) {
      if (getLogicalConnectionName(otherRoute) === connectionName) continue
      for (
        let otherIndex = 0;
        otherIndex < otherRoute.route.length - 1;
        otherIndex++
      ) {
        const otherStart = otherRoute.route[otherIndex]!
        const otherEnd = otherRoute.route[otherIndex + 1]!
        if (start.z !== otherStart.z || start.z !== otherEnd.z) continue
        const requiredDistance =
          input.route.traceThickness / 2 +
          otherRoute.traceThickness / 2 +
          input.obstacleMargin
        if (
          getMinimumSegmentDistance(start, end, otherStart, otherEnd) <
          requiredDistance
        )
          return false
      }
    }
  }
  return true
}
import { getSegmentLength } from "../route-geometry"
import type { HighDensityRoute, RoutePoint } from "../types"
import type { MeanderPlacement } from "./internal-types"

export type MeanderGeometryInput = {
  route: HighDensityRoute
  segmentIndex: number
  toothCount: number
  toothPitch: number
  toothDepths: number[]
  placement: MeanderPlacement
}

const CURVE_SEGMENT_COUNT = 6

const roundMeanderCorners = (points: RoutePoint[]): RoutePoint[] => {
  if (points.length < 3) return points
  const roundedPoints: RoutePoint[] = [{ ...points[0]! }]
  for (let index = 1; index < points.length - 1; index++) {
    const previous = points[index - 1]!
    const corner = points[index]!
    const next = points[index + 1]!
    const incomingLength = Math.hypot(
      corner.x - previous.x,
      corner.y - previous.y,
    )
    const outgoingLength = Math.hypot(next.x - corner.x, next.y - corner.y)
    if (incomingLength === 0 || outgoingLength === 0)
      throw new Error(
        "LengthMatchingSolver: meander contains a zero-length segment",
      )
    const incoming = {
      x: (corner.x - previous.x) / incomingLength,
      y: (corner.y - previous.y) / incomingLength,
    }
    const outgoing = {
      x: (next.x - corner.x) / outgoingLength,
      y: (next.y - corner.y) / outgoingLength,
    }
    if (Math.abs(incoming.x * outgoing.y - incoming.y * outgoing.x) < 1e-9) {
      roundedPoints.push({ ...corner })
      continue
    }
    const radius = Math.min(incomingLength, outgoingLength) / 2
    const curveStart = {
      ...corner,
      x: corner.x - incoming.x * radius,
      y: corner.y - incoming.y * radius,
    }
    const curveEnd = {
      ...corner,
      x: corner.x + outgoing.x * radius,
      y: corner.y + outgoing.y * radius,
    }
    const lastRoundedPoint = roundedPoints.at(-1)!
    if (
      curveStart.x !== lastRoundedPoint.x ||
      curveStart.y !== lastRoundedPoint.y
    )
      roundedPoints.push(curveStart)
    for (let segment = 1; segment < CURVE_SEGMENT_COUNT; segment++) {
      const progress = segment / CURVE_SEGMENT_COUNT
      const remaining = 1 - progress
      roundedPoints.push({
        ...corner,
        x:
          remaining ** 2 * curveStart.x +
          2 * remaining * progress * corner.x +
          progress ** 2 * curveEnd.x,
        y:
          remaining ** 2 * curveStart.y +
          2 * remaining * progress * corner.y +
          progress ** 2 * curveEnd.y,
      })
    }
    roundedPoints.push(curveEnd)
  }
  roundedPoints.push({ ...points[points.length - 1]! })
  return roundedPoints
}

export const createMeanderReplacement = (
  input: MeanderGeometryInput,
): RoutePoint[] => {
  if (input.toothDepths.length !== input.toothCount)
    throw new Error(
      `LengthMatchingSolver: expected ${input.toothCount} tooth depths, received ${input.toothDepths.length}`,
    )
  if (
    input.toothDepths.some(
      (toothDepth) => !Number.isFinite(toothDepth) || toothDepth < 0,
    )
  )
    throw new Error(
      "LengthMatchingSolver: every meander tooth depth must be a non-negative finite number",
    )
  const start = input.route.route[input.segmentIndex]!
  const end = input.route.route[input.segmentIndex + 1]!
  const segmentLength = getSegmentLength(start, end)
  const tangent = {
    x: (end.x - start.x) / segmentLength,
    y: (end.y - start.y) / segmentLength,
  }
  const occupiedLength = (input.toothCount - 0.5) * input.toothPitch
  const leadLength = (segmentLength - occupiedLength) / 2
  const replacement: RoutePoint[] = [{ ...start }]
  for (let toothIndex = 0; toothIndex < input.toothCount; toothIndex++) {
    const toothDepth = input.toothDepths[toothIndex]!
    if (toothDepth === 0) continue
    const normalSign =
      input.placement === "balanced"
        ? toothIndex % 2 === 0
          ? -1
          : 1
        : input.placement === "negative"
          ? -1
          : 1
    const normal = { x: -tangent.y * normalSign, y: tangent.x * normalSign }
    const entryDistance = leadLength + toothIndex * input.toothPitch
    const exitDistance = entryDistance + input.toothPitch / 2
    const entry = {
      ...start,
      x: start.x + tangent.x * entryDistance,
      y: start.y + tangent.y * entryDistance,
    }
    replacement.push(
      entry,
      {
        ...entry,
        x: entry.x + normal.x * toothDepth,
        y: entry.y + normal.y * toothDepth,
      },
      {
        ...start,
        x: start.x + tangent.x * exitDistance + normal.x * toothDepth,
        y: start.y + tangent.y * exitDistance + normal.y * toothDepth,
      },
      {
        ...start,
        x: start.x + tangent.x * exitDistance,
        y: start.y + tangent.y * exitDistance,
      },
    )
  }
  replacement.push({ ...end })
  return roundMeanderCorners(replacement)
}

/** Construct a variable-height meander with tangentially rounded turns. */
export const replaceSegmentWithMeander = (
  input: MeanderGeometryInput,
): RoutePoint[] => [
  ...input.route.route.slice(0, input.segmentIndex),
  ...createMeanderReplacement(input),
  ...input.route.route.slice(input.segmentIndex + 2),
]

import type {
  PlannedAttemptTarget,
  RegressionAttempt,
  SegmentCandidate,
} from "./internal-types"

/** A quality-ranked selection of same-style meander segments. */
export type PartialMeanderPlan = {
  attempts: RegressionAttempt[]
}

type SegmentPitchOptions = {
  attempts: RegressionAttempt[]
  maximumCapacityAttempt: RegressionAttempt
}

const ADDITIONAL_SEGMENT_PENALTY = 3

/** Compare plans without allowing extra segments to inflate a summed score. */
export const getMeanderPlanQualityScore = (
  attempts: Pick<RegressionAttempt, "qualityScore">[],
): number => {
  if (attempts.length === 0)
    throw new Error("LengthMatchingSolver: cannot score an empty meander plan")
  const meanQuality =
    attempts.reduce((total, attempt) => total + attempt.qualityScore, 0) /
    attempts.length
  return meanQuality - ADDITIONAL_SEGMENT_PENALTY * (attempts.length - 1)
}

/** Create a stable identity for a geometry choice on a routed segment. */
export const getRegressionAttemptKey = (
  attempt: Pick<
    SegmentCandidate,
    | "routeIndex"
    | "segmentIndex"
    | "toothCount"
    | "placement"
    | "toothPitch"
    | "heightProfile"
    | "maximumDepth"
    | "minimumHeight"
  >,
): string =>
  [
    attempt.routeIndex,
    attempt.segmentIndex,
    attempt.toothCount,
    attempt.placement,
    attempt.toothPitch,
    attempt.heightProfile,
    attempt.maximumDepth,
    attempt.minimumHeight,
  ].join(":")

// Pitch is selected per segment after target allocation, so unequal segment
// lengths can still participate in one tooth-count/profile plan.
const getMeanderStyleKey = (attempt: SegmentCandidate): string =>
  [attempt.toothCount, attempt.placement, attempt.heightProfile].join(":")

/** Divide a target across selected attempts without exceeding their capacities. */
export const getPlannedAttemptTargets = (input: {
  attempts: RegressionAttempt[]
  targetAddedLength: number
}): Map<string, PlannedAttemptTarget> => {
  const targets = new Map<string, PlannedAttemptTarget>()
  const attempts = [...input.attempts].sort(
    (left, right) => left.addedLength - right.addedLength,
  )
  let remainingLength = input.targetAddedLength
  for (let index = 0; index < attempts.length; index++) {
    const attempt = attempts[index]!
    const target = Math.min(
      attempt.addedLength,
      remainingLength / (attempts.length - index),
    )
    targets.set(getRegressionAttemptKey(attempt), {
      routeIndex: attempt.routeIndex,
      segmentIndex: attempt.segmentIndex,
      targetAddedLength: target,
    })
    remainingLength -= target
  }
  return targets
}

/** Choose the fewest same-style segment choices that can supply the target. */
export const selectPartialMeanderPlan = (input: {
  attempts: RegressionAttempt[]
  targetAddedLength: number
  lengthTolerance: number
}): PartialMeanderPlan | null => {
  const attemptsByStyle = new Map<string, Map<string, RegressionAttempt[]>>()
  for (const attempt of input.attempts) {
    const segmentKey = `${attempt.routeIndex}:${attempt.segmentIndex}`
    const styleKey = getMeanderStyleKey(attempt)
    const attemptsBySegment = attemptsByStyle.get(styleKey)
    if (!attemptsBySegment) {
      attemptsByStyle.set(styleKey, new Map([[segmentKey, [attempt]]]))
      continue
    }
    const segmentAttempts = attemptsBySegment.get(segmentKey)
    if (!segmentAttempts) attemptsBySegment.set(segmentKey, [attempt])
    else segmentAttempts.push(attempt)
  }
  let selectedPlan: PartialMeanderPlan | null = null
  for (const attemptsBySegment of attemptsByStyle.values()) {
    const segmentPitchOptions: SegmentPitchOptions[] = [
      ...attemptsBySegment.values(),
    ]
      .map((attempts) => ({
        attempts,
        maximumCapacityAttempt: attempts.reduce((bestAttempt, attempt) =>
          attempt.addedLength > bestAttempt.addedLength ? attempt : bestAttempt,
        ),
      }))
      .sort(
        (left, right) =>
          right.maximumCapacityAttempt.addedLength -
          left.maximumCapacityAttempt.addedLength,
      )
    let availableLength = 0
    for (let index = 0; index < segmentPitchOptions.length; index++) {
      availableLength +=
        segmentPitchOptions[index]!.maximumCapacityAttempt.addedLength
      if (availableLength + input.lengthTolerance < input.targetAddedLength)
        continue
      const selectedSegmentOptions = segmentPitchOptions.slice(0, index + 1)
      const capacityAttempts = selectedSegmentOptions.map(
        (options) => options.maximumCapacityAttempt,
      )
      const capacityTargets = getPlannedAttemptTargets({
        attempts: capacityAttempts,
        targetAddedLength: input.targetAddedLength,
      })
      const plannedAttempts = selectedSegmentOptions.map((options) => {
        const maximumCapacityTarget = capacityTargets.get(
          getRegressionAttemptKey(options.maximumCapacityAttempt),
        )
        if (!maximumCapacityTarget)
          throw new Error(
            `LengthMatchingSolver: missing capacity target for ${getRegressionAttemptKey(options.maximumCapacityAttempt)}`,
          )
        const feasibleAttempts = options.attempts.filter(
          (attempt) =>
            attempt.addedLength + input.lengthTolerance >=
            maximumCapacityTarget.targetAddedLength,
        )
        if (feasibleAttempts.length === 0)
          throw new Error(
            `LengthMatchingSolver: no pitch can supply planned target for route ${options.maximumCapacityAttempt.routeIndex} segment ${options.maximumCapacityAttempt.segmentIndex}`,
          )
        return feasibleAttempts.reduce((bestAttempt, attempt) =>
          attempt.qualityScore > bestAttempt.qualityScore ||
          (attempt.qualityScore === bestAttempt.qualityScore &&
            attempt.toothPitch > bestAttempt.toothPitch)
            ? attempt
            : bestAttempt,
        )
      })
      const planQualityScore = getMeanderPlanQualityScore(plannedAttempts)
      if (!selectedPlan) {
        selectedPlan = { attempts: plannedAttempts }
        break
      }
      const selectedPlanQualityScore = getMeanderPlanQualityScore(
        selectedPlan.attempts,
      )
      if (
        plannedAttempts.length < selectedPlan.attempts.length ||
        (plannedAttempts.length === selectedPlan.attempts.length &&
          planQualityScore > selectedPlanQualityScore)
      )
        selectedPlan = { attempts: plannedAttempts }
      break
    }
  }
  return selectedPlan
}
