  }

  private tryCandidate(activePair: ActivePair): void {
    let candidate: ActivePair["candidates"][number] | undefined
    while (!candidate) {
      const nextCandidate = activePair.candidates[activePair.candidateIndex++]
      if (!nextCandidate) break
