              : bestAttempt,
          null,
        )
      const partialPlan = selectPartialMeanderPlan({
        attempts: activePair.partialAttempts,
        targetAddedLength: activePair.remainingAddedLength,
        lengthTolerance: activePair.pair.lengthTolerance,
      })
