        bestFullAttempt &&
        (!partialPlan ||
          bestFullAttempt.qualityScore >=
            getMeanderPlanQualityScore(partialPlan.attempts))
      ) {
        this.acceptAttempt(activePair, bestFullAttempt)
        return
