/** Compose the standard route, obstacle, and attempt debug layers in draw order. */
export const createLengthMatchingVisualization = (
  input: LengthMatchingVisualizationInput,
): GraphicsObject => {
  const graphics: LengthMatchingGraphics = {
    lines: [],
    points: [],
    rects: [],
    circles: [],
  }
  const theme = createLengthMatchingColorTheme(input.colorMap)
  buildRouteGraphics({ routes: input.routes, theme, graphics })
  buildObstacleGraphics({
    obstacles: input.obstacles,
    bounds: input.bounds,
    layerCount: input.layerCount,
    theme,
    graphics,
  })
  buildAttemptGraphics({
    routes: input.routes,
    attempt: input.currentAttempt,
    activePair: input.activePair,
    showAttempt: !input.solved,
    theme,
    graphics,
  })
  return {
    ...graphics,
  }
}
import type { HighDensityRoute } from "../../types"
