/** Append the latest candidate diagnostic without mutating solver state. */
export const buildAttemptGraphics = (input: {
  routes: HighDensityRoute[]
  attempt: RegressionAttempt | null
  activePair: ActivePair | null
  showAttempt: boolean
  theme: LengthMatchingColorTheme
  graphics: LengthMatchingGraphics
}): void => {
  if (!input.showAttempt) return
  if (!input.attempt) {
    appendSelectedSegmentGraphics(input)
    return
  }
  const route = input.routes[input.attempt.routeIndex]!
  const [start, end] = input.attempt.testedSegment
  const connectionColor = input.theme.getConnectionColor(
    input.attempt.connectionName,
  )
  input.graphics.lines.push({
    points: [start, end],
    strokeColor: input.theme.getTestedSegmentColor(connectionColor),
    strokeWidth: route.traceThickness,
    strokeDash: [0.15, 0.15],
    layer: getGraphicsLayerForRoute(start.z),
  })
  if (!input.attempt.valid)
    input.graphics.lines.push({
      points: input.attempt.meanderPoints.map(({ x, y }) => ({ x, y })),
      strokeColor: input.theme.getRejectedCandidateColor(connectionColor),
      strokeWidth: route.traceThickness,
      strokeDash: [0.1, 0.1],
      layer: getGraphicsLayerForRoute(start.z),
    })
  else
    input.graphics.lines.push({
      points: input.attempt.meanderPoints.map(({ x, y }) => ({ x, y })),
      strokeColor: "rgba(234, 179, 8, 0.6)",
      strokeWidth: route.traceThickness * 2,
      strokeDash: [0.1, 0.1],
      layer: getGraphicsLayerForRoute(start.z),
    })
  input.graphics.points.push(
    {
      x: start.x,
      y: start.y,
      color: connectionColor,
      layer: getGraphicsLayerForRoute(start.z),
    },
    {
      x: end.x,
      y: end.y,
      color: connectionColor,
      layer: getGraphicsLayerForRoute(end.z),
    },
  )
}

const appendSelectedSegmentGraphics = (input: {
  routes: HighDensityRoute[]
  activePair: ActivePair | null
  theme: LengthMatchingColorTheme
  graphics: LengthMatchingGraphics
}): void => {
  const candidate =
    input.activePair?.candidates[input.activePair.candidateIndex]
  if (!candidate) return
  const route = input.routes[candidate.routeIndex]
  if (!route) return
  const start = route.route[candidate.segmentIndex]
  const end = route.route[candidate.segmentIndex + 1]
  if (!start || !end) return
  input.graphics.lines.push({
    points: [start, end],
    strokeColor: "rgba(234, 179, 8, 0.6)",
    strokeWidth: route.traceThickness * 2,
    strokeDash: [0.1, 0.1],
    layer: getGraphicsLayerForRoute(start.z),
  })
}
import { transparentize } from "polished"

/** Color decisions shared by every length-matching debug graphics builder. */
export type LengthMatchingColorTheme = {
  getConnectionColor: (
    connectionName: string,
    routeConnectionName?: string,
  ) => string
  getInnerLayerConnectionColor: (color: string) => string
  getTestedSegmentColor: (color: string) => string
  getRejectedCandidateColor: (color: string) => string
  boardBounds: { fill: string; stroke: string }
  obstacle: { fill: string; stroke: string }
  via: { fill: string; stroke: string }
}

const getDeterministicConnectionColor = (connectionName: string): string => {
  if (!connectionName) return "rgba(0, 0, 0, 0.5)"
  const characterSum = connectionName
    .split("")
    .reduce((total, character) => total + character.charCodeAt(0), 0)
  return `hsl(${((characterSum * 300) / connectionName.length) % 360}, 100%, 50%)`
}

/** Create the deterministic palette used by all length-matching visualizations. */
export const createLengthMatchingColorTheme = (
  colorMap: Record<string, string>,
): LengthMatchingColorTheme => {
  for (const color of Object.values(colorMap)) transparentize(0, color)
  return {
    getConnectionColor: (connectionName, routeConnectionName) =>
      colorMap[connectionName] ??
      (routeConnectionName ? colorMap[routeConnectionName] : undefined) ??
      getDeterministicConnectionColor(connectionName),
    getInnerLayerConnectionColor: (color) => transparentize(0.5, color),
    getTestedSegmentColor: (color) => transparentize(0.55, color),
    getRejectedCandidateColor: (color) => transparentize(0.45, color),
    boardBounds: { fill: "rgba(30,41,59,0.03)", stroke: "rgba(30,41,59,0.55)" },
    obstacle: { fill: "rgba(255,0,0,0.25)", stroke: "rgba(255,0,0,0.5)" },
    via: { fill: "blue", stroke: "none" },
  }
}
import type { Obstacle } from "../../types"

export const getGraphicsLayerForRoute = (z: number): string => `z${z}`

/** Convert obstacle PCB layer names into the graphics-debug layer format. */
export const getGraphicsLayerForObstacle = (
  obstacle: Obstacle,
  layerCount: number,
): string => {
  const layers = obstacle.layers.map((layerName) => {
    if (layerName === "top") return 0
    if (layerName === "bottom") return layerCount - 1
    const innerLayerIndex = Number.parseInt(layerName.replace("inner", ""), 10)
    if (!Number.isInteger(innerLayerIndex))
      throw new Error(`LengthMatchingSolver: unknown layer name "${layerName}"`)
    return innerLayerIndex
  })
  return `z${layers.join(",")}`
}

import { doSegmentsIntersect } from "@tscircuit/math-utils"
import type { HighDensityRoute, RoutePoint } from "./types"

type Point2D = { readonly x: number; readonly y: number }

const pointToSegmentDistance = (
  point: Point2D,
  segmentStart: Point2D,
  segmentEnd: Point2D,
): number => {
  const segment = {
    x: segmentEnd.x - segmentStart.x,
    y: segmentEnd.y - segmentStart.y,
  }
  const fromStart = {
    x: point.x - segmentStart.x,
    y: point.y - segmentStart.y,
  }
  const segmentLengthSquared = segment.x ** 2 + segment.y ** 2
  const projection =
    segmentLengthSquared === 0
      ? 0
      : Math.max(
          0,
          Math.min(
            1,
            (fromStart.x * segment.x + fromStart.y * segment.y) /
              segmentLengthSquared,
          ),
        )
  return Math.hypot(
    point.x - (segmentStart.x + projection * segment.x),
    point.y - (segmentStart.y + projection * segment.y),
  )
}

/** Return the Euclidean length of a same-layer or multi-layer route segment. */
export const getSegmentLength = (start: RoutePoint, end: RoutePoint): number =>
  Math.hypot(end.x - start.x, end.y - start.y)

/** Sum the planar lengths of every consecutive segment in a routed connection. */
export const getRouteLength = (route: HighDensityRoute): number => {
  let length = 0
  for (let index = 0; index < route.route.length - 1; index++) {
    length += getSegmentLength(route.route[index]!, route.route[index + 1]!)
  }
  return length
}

/** Return the minimum planar clearance between two closed line segments. */
export const getMinimumSegmentDistance = (
  firstStart: Point2D,
  firstEnd: Point2D,
  secondStart: Point2D,
  secondEnd: Point2D,
): number => {
  if (doSegmentsIntersect(firstStart, firstEnd, secondStart, secondEnd)) {
    return 0
  }
  return Math.min(
    pointToSegmentDistance(firstStart, secondStart, secondEnd),
    pointToSegmentDistance(firstEnd, secondStart, secondEnd),
    pointToSegmentDistance(secondStart, firstStart, firstEnd),
    pointToSegmentDistance(secondEnd, firstStart, firstEnd),
  )
}
