import type { LengthMatchingConfig } from "../internal-types"
import type { LengthMatchingSolverParams } from "../types"

/** Validate public options once and resolve defaults for every internal module. */
export const validateAndResolveParams = (
  params: LengthMatchingSolverParams,
): LengthMatchingConfig => {
  const maximumMeanderDepth = params.maximumMeanderDepth ?? 5
  const maxToothCount = params.maxToothCount ?? 12
  if (!Number.isFinite(maximumMeanderDepth) || maximumMeanderDepth <= 0) {
    throw new Error(
      "LengthMatchingSolver: maximumMeanderDepth must be a positive finite number",
    )
  }
  if (
    params.minimumToothPitch !== undefined &&
    (!Number.isFinite(params.minimumToothPitch) ||
      params.minimumToothPitch <= 0)
  ) {
    throw new Error(
      "LengthMatchingSolver: minimumToothPitch must be a positive finite number",
    )
  }
  if (
    params.minMeanderGap !== undefined &&
    (!Number.isFinite(params.minMeanderGap) || params.minMeanderGap <= 0)
  ) {
    throw new Error(
      "LengthMatchingSolver: minMeanderGap must be a positive finite number",
    )
  }
  if (
    params.minMeanderHeight !== undefined &&
    (!Number.isFinite(params.minMeanderHeight) || params.minMeanderHeight <= 0)
  ) {
    throw new Error(
      "LengthMatchingSolver: minMeanderHeight must be a positive finite number",
    )
  }
  if (
    params.minMeanderHeight !== undefined &&
    params.minMeanderHeight > maximumMeanderDepth
  ) {
    throw new Error(
      "LengthMatchingSolver: minMeanderHeight cannot exceed maximumMeanderDepth",
    )
  }
  if (
    !Number.isFinite(maxToothCount) ||
    !Number.isInteger(maxToothCount) ||
    maxToothCount <= 0
  ) {
    throw new Error(
      "LengthMatchingSolver: maxToothCount must be a positive finite integer",
    )
  }
  return {
    maximumMeanderDepth,
    minimumToothPitch: params.minimumToothPitch,
    minMeanderGap: params.minMeanderGap,
    minMeanderHeight: params.minMeanderHeight,
    maxToothCount,
    obstacles: params.obstacles ?? [],
    bounds: params.bounds,
    obstacleMargin: params.obstacleMargin ?? 0.15,
    layerCount: params.layerCount ?? 2,
    colorMap: params.colorMap ?? {},
  }
}

import { getMinimumSegmentDistance } from "../../route-geometry"
import type { HighDensityRoute, Obstacle, RoutePoint } from "../../types"
import { getLogicalConnectionName } from "../connection-routes"

/** Check candidate bounds, obstacle clearance, and clearance from other connections. */
export const isCandidateGeometryValid = (input: {
  route: HighDensityRoute
  meanderPoints: RoutePoint[]
  routedRoutes: HighDensityRoute[]
  obstacles: Obstacle[]
  bounds?: { minX: number; maxX: number; minY: number; maxY: number }
  layerCount: number
  obstacleMargin: number
}): boolean => {
  const isObstacleOnLayer = (
    obstacle: Obstacle,
    z: number,
    layerCount: number,
  ): boolean => {
    if (obstacle.zLayers) return obstacle.zLayers.includes(z)
    return obstacle.layers.some(
      (layer) =>
        (layer === "top" && z === 0) ||
        (layer === "bottom" && z === layerCount - 1) ||
        layer === `inner${z}`,
    )
  }
  const segmentTouchesInflatedObstacle = (
    start: RoutePoint,
    end: RoutePoint,
    obstacle: Obstacle,
    margin: number,
  ): boolean => {
    const minX = obstacle.center.x - obstacle.width / 2 - margin
    const maxX = obstacle.center.x + obstacle.width / 2 + margin
    const minY = obstacle.center.y - obstacle.height / 2 - margin
    const maxY = obstacle.center.y + obstacle.height / 2 + margin
    if (
      (start.x >= minX &&
        start.x <= maxX &&
        start.y >= minY &&
        start.y <= maxY) ||
      (end.x >= minX && end.x <= maxX && end.y >= minY && end.y <= maxY)
    )
      return true
    const corners = [
      { x: minX, y: minY },
      { x: maxX, y: minY },
      { x: maxX, y: maxY },
      { x: minX, y: maxY },
    ]
    return corners.some(
      (corner, index) =>
        getMinimumSegmentDistance(
          start,
          end,
          corner,
          corners[(index + 1) % corners.length]!,
        ) === 0,
    )
  }
  if (
    input.bounds &&
    input.meanderPoints.some(
      (point) =>
        point.x < input.bounds!.minX ||
        point.x > input.bounds!.maxX ||
        point.y < input.bounds!.minY ||
        point.y > input.bounds!.maxY,
    )
  )
    return false
  const connectionName = getLogicalConnectionName(input.route)
  const obstacleMargin = input.route.traceThickness / 2 + input.obstacleMargin
  for (let index = 0; index < input.meanderPoints.length - 1; index++) {
    const start = input.meanderPoints[index]!
    const end = input.meanderPoints[index + 1]!
    for (const obstacle of input.obstacles) {
      if (!isObstacleOnLayer(obstacle, start.z, input.layerCount)) continue
      const isTerminalLead =
        index === 0 || index === input.meanderPoints.length - 2
      if (obstacle.connectedTo.includes(connectionName) && isTerminalLead)
        continue
      if (segmentTouchesInflatedObstacle(start, end, obstacle, obstacleMargin))
        return false
    }
    for (const otherRoute of input.routedRoutes) {
      if (getLogicalConnectionName(otherRoute) === connectionName) continue
      for (
        let otherIndex = 0;
        otherIndex < otherRoute.route.length - 1;
        otherIndex++
      ) {
        const otherStart = otherRoute.route[otherIndex]!
        const otherEnd = otherRoute.route[otherIndex + 1]!
        if (start.z !== otherStart.z || start.z !== otherEnd.z) continue
        const requiredDistance =
          input.route.traceThickness / 2 +
          otherRoute.traceThickness / 2 +
          input.obstacleMargin
        if (
          getMinimumSegmentDistance(start, end, otherStart, otherEnd) <
          requiredDistance
        )
          return false
      }
    }
  }
  return true
}

import { getSegmentLength } from "../../route-geometry"
import type { HighDensityRoute, RoutePoint } from "../../types"
import type { MeanderPlacement } from "../internal-types"

export type MeanderGeometryInput = {
  route: HighDensityRoute
  segmentIndex: number
  toothCount: number
  toothPitch: number
  toothDepths: number[]
  placement: MeanderPlacement
}

const CURVE_SEGMENT_COUNT = 6

export const createMeanderReplacement = (
  input: MeanderGeometryInput,
): RoutePoint[] => {
  const roundMeanderCorners = (points: RoutePoint[]): RoutePoint[] => {
    if (points.length < 3) return points
    const roundedPoints: RoutePoint[] = [{ ...points[0]! }]
    for (let index = 1; index < points.length - 1; index++) {
      const previous = points[index - 1]!
      const corner = points[index]!
      const next = points[index + 1]!
      const incomingLength = Math.hypot(
        corner.x - previous.x,
        corner.y - previous.y,
      )
      const outgoingLength = Math.hypot(next.x - corner.x, next.y - corner.y)
      if (incomingLength === 0 || outgoingLength === 0)
        throw new Error(
          "LengthMatchingSolver: meander contains a zero-length segment",
        )
      const incoming = {
        x: (corner.x - previous.x) / incomingLength,
        y: (corner.y - previous.y) / incomingLength,
      }
      const outgoing = {
        x: (next.x - corner.x) / outgoingLength,
        y: (next.y - corner.y) / outgoingLength,
      }
      if (Math.abs(incoming.x * outgoing.y - incoming.y * outgoing.x) < 1e-9) {
        roundedPoints.push({ ...corner })
        continue
      }
      const radius = Math.min(incomingLength, outgoingLength) / 2
      const curveStart = {
        ...corner,
        x: corner.x - incoming.x * radius,
        y: corner.y - incoming.y * radius,
      }
      const curveEnd = {
        ...corner,
        x: corner.x + outgoing.x * radius,
        y: corner.y + outgoing.y * radius,
      }
      const lastRoundedPoint = roundedPoints.at(-1)!
      if (
        curveStart.x !== lastRoundedPoint.x ||
        curveStart.y !== lastRoundedPoint.y
      )
        roundedPoints.push(curveStart)
      for (let segment = 1; segment < CURVE_SEGMENT_COUNT; segment++) {
        const progress = segment / CURVE_SEGMENT_COUNT
        const remaining = 1 - progress
        roundedPoints.push({
          ...corner,
          x:
            remaining ** 2 * curveStart.x +
            2 * remaining * progress * corner.x +
            progress ** 2 * curveEnd.x,
          y:
            remaining ** 2 * curveStart.y +
            2 * remaining * progress * corner.y +
            progress ** 2 * curveEnd.y,
        })
      }
      roundedPoints.push(curveEnd)
    }
    roundedPoints.push({ ...points[points.length - 1]! })
    return roundedPoints
  }
  if (input.toothDepths.length !== input.toothCount)
    throw new Error(
      `LengthMatchingSolver: expected ${input.toothCount} tooth depths, received ${input.toothDepths.length}`,
    )
  if (
    input.toothDepths.some(
      (toothDepth) => !Number.isFinite(toothDepth) || toothDepth < 0,
    )
  )
    throw new Error(
      "LengthMatchingSolver: every meander tooth depth must be a non-negative finite number",
    )
  const start = input.route.route[input.segmentIndex]!
  const end = input.route.route[input.segmentIndex + 1]!
  const segmentLength = getSegmentLength(start, end)
  const tangent = {
    x: (end.x - start.x) / segmentLength,
    y: (end.y - start.y) / segmentLength,
  }
  const occupiedLength = (input.toothCount - 0.5) * input.toothPitch
  const leadLength = (segmentLength - occupiedLength) / 2
  const replacement: RoutePoint[] = [{ ...start }]
  for (let toothIndex = 0; toothIndex < input.toothCount; toothIndex++) {
    const toothDepth = input.toothDepths[toothIndex]!
    if (toothDepth === 0) continue
    const normalSign =
      input.placement === "balanced"
        ? toothIndex % 2 === 0
          ? -1
          : 1
        : input.placement === "negative"
          ? -1
          : 1
    const normal = { x: -tangent.y * normalSign, y: tangent.x * normalSign }
    const entryDistance = leadLength + toothIndex * input.toothPitch
    const exitDistance = entryDistance + input.toothPitch / 2
    const entry = {
      ...start,
      x: start.x + tangent.x * entryDistance,
      y: start.y + tangent.y * entryDistance,
    }
    replacement.push(
      entry,
      {
        ...entry,
        x: entry.x + normal.x * toothDepth,
        y: entry.y + normal.y * toothDepth,
      },
      {
        ...start,
        x: start.x + tangent.x * exitDistance + normal.x * toothDepth,
        y: start.y + tangent.y * exitDistance + normal.y * toothDepth,
      },
      {
        ...start,
        x: start.x + tangent.x * exitDistance,
        y: start.y + tangent.y * exitDistance,
      },
    )
  }
  replacement.push({ ...end })
  return roundMeanderCorners(replacement)
}

import type { RoutePoint } from "../../types"
import {
  createMeanderReplacement,
  type MeanderGeometryInput,
} from "./createMeanderReplacement"

/** Construct a variable-height meander with tangentially rounded turns. */
export const replaceSegmentWithMeander = (
  input: MeanderGeometryInput,
): RoutePoint[] => [
  ...input.route.route.slice(0, input.segmentIndex),
  ...createMeanderReplacement(input),
  ...input.route.route.slice(input.segmentIndex + 2),
]

import { getRouteLength } from "../../route-geometry"
import type { HighDensityRoute, RoutePoint } from "../../types"
import type {
  MeanderHeightProfile,
  RegressionAttempt,
  SegmentCandidate,
} from "../internal-types"
import { getMeanderQualityScore } from "../meander-quality"
import { createMeanderReplacement } from "./createMeanderReplacement"
import { replaceSegmentWithMeander } from "./replaceSegmentWithMeander"

const DEPTH_SEARCH_ITERATIONS = 32

/** Fit a scale factor over clearance-limited tooth depths and predict a route. */
export const evaluateMeanderCandidate = (input: {
  candidate: SegmentCandidate
  route: HighDensityRoute
  connectionName: string
  targetAddedLength: number
  lengthTolerance: number
  isGeometryValid: (meanderPoints: RoutePoint[]) => boolean
}): RegressionAttempt => {
  const getToothHeightWeights = (profile: {
    toothCount: number
    heightProfile: MeanderHeightProfile
  }): number[] => {
    if (profile.heightProfile !== "tapered")
      return Array<number>(profile.toothCount).fill(1)
    const weights = Array.from({ length: profile.toothCount }, (_, toothIndex) =>
      Math.sin((Math.PI * (toothIndex + 1)) / (profile.toothCount + 1)),
    )
    const maximumWeight = Math.max(...weights)
    return weights.map((weight) => weight / maximumWeight)
  }
  const getMaximumToothDepths = (): number[] => {
    const maximumToothDepths: number[] = []
    for (
      let toothIndex = 0;
      toothIndex < input.candidate.toothCount;
      toothIndex++
    ) {
      const maximumProfile = Array<number>(input.candidate.toothCount).fill(0)
      maximumProfile[toothIndex] = input.candidate.maximumDepth
      const maximumReplacement = createMeanderReplacement({
        ...input.candidate,
        route: input.route,
        toothDepths: maximumProfile,
      })
      if (input.isGeometryValid(maximumReplacement)) {
        maximumToothDepths.push(input.candidate.maximumDepth)
        continue
      }
      let validDepth = 0
      let invalidDepth = input.candidate.maximumDepth
      for (
        let iteration = 0;
        iteration < DEPTH_SEARCH_ITERATIONS;
        iteration++
      ) {
        const testedDepth = (validDepth + invalidDepth) / 2
        const testedProfile = Array<number>(input.candidate.toothCount).fill(0)
        testedProfile[toothIndex] = testedDepth
        const testedReplacement = createMeanderReplacement({
          ...input.candidate,
          route: input.route,
          toothDepths: testedProfile,
        })
        if (input.isGeometryValid(testedReplacement)) validDepth = testedDepth
        else invalidDepth = testedDepth
      }
      maximumToothDepths.push(validDepth)
    }
    return maximumToothDepths
  }
  const findCappedDepthProfileForTargetLength = (profile: {
    maximumToothDepths: number[]
    toothHeightWeights: number[]
    originalLength: number
    targetAddedLength: number
  }): { toothDepths: number[]; depthLevel: number } => {
    let lowerDepthLevel = 0
    let upperDepthLevel = input.candidate.maximumDepth
    for (
      let iteration = 0;
      iteration < DEPTH_SEARCH_ITERATIONS;
      iteration++
    ) {
      const depthLevel = (lowerDepthLevel + upperDepthLevel) / 2
      const toothDepths = profile.maximumToothDepths.map(
        (maximumDepth, toothIndex) =>
          Math.min(
            maximumDepth,
            depthLevel * profile.toothHeightWeights[toothIndex]!,
          ),
      )
      const candidateRoute = replaceSegmentWithMeander({
        ...input.candidate,
        route: input.route,
        toothDepths,
      })
      const addedLength =
        getRouteLength({ ...input.route, route: candidateRoute }) -
        profile.originalLength
      const meanderPoints = createMeanderReplacement({
        ...input.candidate,
        route: input.route,
        toothDepths,
      })
      if (!input.isGeometryValid(meanderPoints)) {
        upperDepthLevel = depthLevel
        continue
      }
      if (addedLength < profile.targetAddedLength)
        lowerDepthLevel = depthLevel
      else upperDepthLevel = depthLevel
    }
    const depthLevel = (lowerDepthLevel + upperDepthLevel) / 2
    return {
      depthLevel,
      toothDepths: profile.maximumToothDepths.map(
        (maximumDepth, toothIndex) =>
          Math.min(
            maximumDepth,
            depthLevel * profile.toothHeightWeights[toothIndex]!,
          ),
      ),
    }
  }
  const originalLength = getRouteLength(input.route)
  const maximumToothDepths = getMaximumToothDepths()
  const toothHeightWeights = getToothHeightWeights(input.candidate)
  const maximumDepthLevel = input.candidate.maximumDepth
  const maximumProfile = maximumToothDepths.map((maximumDepth, toothIndex) =>
    Math.min(maximumDepth, maximumDepthLevel * toothHeightWeights[toothIndex]!),
  )
  const sampleScaleFactors: [number, number] = [0.25, 0.75]
  const firstSampleDepths = maximumProfile.map(
    (maximumDepth) => maximumDepth * sampleScaleFactors[0],
  )
  const secondSampleDepths = maximumProfile.map(
    (maximumDepth) => maximumDepth * sampleScaleFactors[1],
  )
  const firstSampleRoute = replaceSegmentWithMeander({
    ...input.candidate,
    route: input.route,
    toothDepths: firstSampleDepths,
  })
  const secondSampleRoute = replaceSegmentWithMeander({
    ...input.candidate,
    route: input.route,
    toothDepths: secondSampleDepths,
  })
  const sampleAddedLengths: [number, number] = [
    getRouteLength({ ...input.route, route: firstSampleRoute }) -
      originalLength,
    getRouteLength({ ...input.route, route: secondSampleRoute }) -
      originalLength,
  ]
  const maximumScaleRoute = replaceSegmentWithMeander({
    ...input.candidate,
    route: input.route,
    toothDepths: maximumProfile,
  })
  const maximumAddedLength =
    getRouteLength({ ...input.route, route: maximumScaleRoute }) -
    originalLength
  const slope =
    (sampleAddedLengths[1] - sampleAddedLengths[0]) /
    (sampleScaleFactors[1] - sampleScaleFactors[0])
  const intercept = sampleAddedLengths[0] - slope * sampleScaleFactors[0]
  const regressionPredictedScaleFactor =
    slope > 0 && Number.isFinite(slope)
      ? (input.targetAddedLength - intercept) / slope
      : 0
  const matchedAddedLength = Math.min(
    input.targetAddedLength,
    maximumAddedLength,
  )
  const fittedProfile =
    input.targetAddedLength > 0 && matchedAddedLength > 0
      ? findCappedDepthProfileForTargetLength({
          maximumToothDepths,
          toothHeightWeights,
          originalLength,
          targetAddedLength: matchedAddedLength,
        })
      : {
          depthLevel: regressionPredictedScaleFactor * maximumDepthLevel,
          toothDepths: maximumProfile.map((maximumDepth) =>
            Math.max(0, maximumDepth * regressionPredictedScaleFactor),
          ),
        }
  const predictedScaleFactor = fittedProfile.depthLevel / maximumDepthLevel
  const predictedToothDepths = fittedProfile.toothDepths
  const predictedRoute = replaceSegmentWithMeander({
    ...input.candidate,
    route: input.route,
    toothDepths: predictedToothDepths,
  })
  const addedLength =
    getRouteLength({ ...input.route, route: predictedRoute }) - originalLength
  const resultingError = Math.abs(matchedAddedLength - addedLength)
  const meanderPoints = createMeanderReplacement({
    ...input.candidate,
    route: input.route,
    toothDepths: predictedToothDepths,
  })
  const scaleIsValid =
    Number.isFinite(predictedScaleFactor) &&
    predictedScaleFactor > 0 &&
    predictedScaleFactor <= 1
  const minimumHeightIsValid = predictedToothDepths.every(
    (toothDepth) =>
      toothDepth === 0 || toothDepth >= input.candidate.minimumHeight,
  )
  const geometryIsValid = input.isGeometryValid(meanderPoints)
  const invalidReason: RegressionAttempt["invalidReason"] = !scaleIsValid
    ? "invalid-scale"
    : resultingError > input.lengthTolerance
      ? "target-error"
      : !geometryIsValid
        ? "invalid-geometry"
        : !minimumHeightIsValid
          ? "below-minimum-height"
          : null
  const outcome = invalidReason
    ? { valid: false as const, invalidReason }
    : { valid: true as const, invalidReason: null }
  const attempt: RegressionAttempt = {
    ...input.candidate,
    connectionName: input.connectionName,
    maximumToothDepths,
    sampleScaleFactors,
    sampleAddedLengths,
    slope,
    intercept,
    predictedScaleFactor,
    predictedToothDepths,
    predictedRoute,
    addedLength,
    maximumAddedLength,
    resultingError,
    testedSegment: [
      { ...input.route.route[input.candidate.segmentIndex]! },
      { ...input.route.route[input.candidate.segmentIndex + 1]! },
    ],
    meanderPoints,
    qualityScore: 0,
    ...outcome,
  }
  return { ...attempt, qualityScore: getMeanderQualityScore(attempt) }
}

import { getRouteLength } from "../../route-geometry"
import type { HighDensityRoute, RoutePoint } from "../../types"
import type {
  MeanderHeightProfile,
  SegmentCandidate,
  ValidRegressionAttempt,
} from "../internal-types"
import { createMeanderReplacement } from "./createMeanderReplacement"
import { evaluateMeanderCandidate } from "./evaluateMeanderCandidate"
import { replaceSegmentWithMeander } from "./replaceSegmentWithMeander"

const DEPTH_SEARCH_ITERATIONS = 32

/** Evaluate the shallowest minimum-height profile, or return null if rejected. */
export const evaluateMinimumMeanderCandidate = (input: {
  candidate: SegmentCandidate
  route: HighDensityRoute
  connectionName: string
  lengthTolerance: number
  isGeometryValid: (meanderPoints: RoutePoint[]) => boolean
}): ValidRegressionAttempt | null => {
  const getToothHeightWeights = (profile: {
    toothCount: number
    heightProfile: MeanderHeightProfile
  }): number[] => {
    if (profile.heightProfile !== "tapered")
      return Array<number>(profile.toothCount).fill(1)
    const weights = Array.from({ length: profile.toothCount }, (_, toothIndex) =>
      Math.sin((Math.PI * (toothIndex + 1)) / (profile.toothCount + 1)),
    )
    const maximumWeight = Math.max(...weights)
    return weights.map((weight) => weight / maximumWeight)
  }
  const toothHeightWeights = getToothHeightWeights(input.candidate)
  const minimumDepthLevel = Math.max(
    ...toothHeightWeights.map(
      (weight) => input.candidate.minimumHeight / weight,
    ),
  )
  // Four final bisection quanta keep a representable minimum-height tooth from
  // being rejected when the last midpoint lands microscopically below it.
  const depthSearchMargin =
    input.candidate.maximumDepth / 2 ** (DEPTH_SEARCH_ITERATIONS - 2)
  const minimumToothDepths = toothHeightWeights.map(
    (weight) => weight * (minimumDepthLevel + depthSearchMargin),
  )
  if (
    minimumToothDepths.some(
      (toothDepth) => toothDepth > input.candidate.maximumDepth,
    )
  )
    return null
  const minimumMeanderPoints = createMeanderReplacement({
    ...input.candidate,
    route: input.route,
    toothDepths: minimumToothDepths,
  })
  if (!input.isGeometryValid(minimumMeanderPoints)) return null
  const minimumRoute = replaceSegmentWithMeander({
    ...input.candidate,
    route: input.route,
    toothDepths: minimumToothDepths,
  })
  const targetAddedLength =
    getRouteLength({ ...input.route, route: minimumRoute }) -
    getRouteLength(input.route)
  const attempt = evaluateMeanderCandidate({
    ...input,
    targetAddedLength,
  })
  return attempt.valid ? attempt : null
}

import { getSegmentLength } from "../../route-geometry"
import type { HighDensityRoute } from "../../types"
import type { MeanderPlacement, SegmentCandidate } from "../internal-types"

const DEFAULT_MIN_MEANDER_GAP = 0.3

/** Enumerate deterministic segment, tooth-count, and side choices for tuning. */
export const createMeanderCandidates = (input: {
  routes: HighDensityRoute[]
  routeIndexes: number[]
  maximumDepth: number
  minimumToothPitch?: number
  minMeanderGap?: number
  minMeanderHeight?: number
  maxToothCount: number
}): SegmentCandidate[] => {
  const candidates: SegmentCandidate[] = []
  for (const routeIndex of input.routeIndexes) {
    const route = input.routes[routeIndex]!
    const minMeanderGap =
      input.minMeanderGap ??
      Math.max(DEFAULT_MIN_MEANDER_GAP, route.traceThickness * 2)
    const minimumTraceCenterlineSpacing = route.traceThickness + minMeanderGap
    const toothPitch = Math.max(
      input.minimumToothPitch ?? 0,
      minimumTraceCenterlineSpacing * 2,
    )
    const minimumHeight =
      input.minMeanderHeight ?? minimumTraceCenterlineSpacing
    for (
      let segmentIndex = 0;
      segmentIndex < route.route.length - 1;
      segmentIndex++
    ) {
      const start = route.route[segmentIndex]!
      const end = route.route[segmentIndex + 1]!
      const segmentLength = getSegmentLength(start, end)
      if (segmentLength <= 0 || start.z !== end.z) continue
      const toothCapacity = Math.min(
        Math.max(0, Math.floor(segmentLength / toothPitch) - 1),
        input.maxToothCount,
      )
      for (let toothCount = 1; toothCount <= toothCapacity; toothCount++) {
        // Explore the open segment as well as the minimum-clearance footprint.
        // The geometric mean supplies one deterministic constrained compromise.
        const maximumRelaxedPitch = segmentLength / (toothCount + 1)
        const pitchOptions = [
          maximumRelaxedPitch,
          Math.sqrt(toothPitch * maximumRelaxedPitch),
          toothPitch,
        ].filter(
          (pitch, pitchIndex, pitches) =>
            pitches.findIndex(
              (otherPitch) => Math.abs(otherPitch - pitch) < 1e-9,
            ) === pitchIndex,
        )
        const placements: MeanderPlacement[] =
          toothCount % 2 === 0
            ? ["balanced", "negative", "positive"]
            : ["negative", "positive"]
        for (const candidatePitch of pitchOptions)
          for (const placement of placements)
            candidates.push({
              routeIndex,
              segmentIndex,
              segmentLength,
              toothCount,
              maximumDepth: input.maximumDepth,
              minimumHeight,
              toothPitch: candidatePitch,
              placement,
              heightProfile: toothCount > 1 ? "tapered" : "uniform",
            })
      }
    }
  }
  const placementPriority: Record<MeanderPlacement, number> = {
    balanced: 0,
    negative: 1,
    positive: 2,
  }
  return candidates.sort(
    (left, right) =>
      left.toothCount - right.toothCount ||
      placementPriority[left.placement] - placementPriority[right.placement] ||
      right.toothPitch - left.toothPitch ||
      right.segmentLength - left.segmentLength,
  )
}

import type { RegressionAttempt, SegmentCandidate } from "../internal-types"
import { getMeanderPlanQualityScore } from "./getMeanderPlanQualityScore"
import { getPlannedAttemptTargets } from "./getPlannedAttemptTargets"
import { getRegressionAttemptKey } from "./getRegressionAttemptKey"

/** A quality-ranked selection of same-style meander segments. */
export type PartialMeanderPlan = {
  attempts: RegressionAttempt[]
}

type SegmentPitchOptions = {
  attempts: RegressionAttempt[]
  maximumCapacityAttempt: RegressionAttempt
}

/** Choose the fewest same-style segment choices that can supply the target. */
export const selectPartialMeanderPlan = (input: {
  attempts: RegressionAttempt[]
  targetAddedLength: number
  lengthTolerance: number
}): PartialMeanderPlan | null => {
  const getMeanderStyleKey = (attempt: SegmentCandidate): string =>
    [attempt.toothCount, attempt.placement, attempt.heightProfile].join(":")
  const attemptsByStyle = new Map<string, Map<string, RegressionAttempt[]>>()
  for (const attempt of input.attempts) {
    const segmentKey = `${attempt.routeIndex}:${attempt.segmentIndex}`
    const styleKey = getMeanderStyleKey(attempt)
    const attemptsBySegment = attemptsByStyle.get(styleKey)
    if (!attemptsBySegment) {
      attemptsByStyle.set(styleKey, new Map([[segmentKey, [attempt]]]))
      continue
    }
    const segmentAttempts = attemptsBySegment.get(segmentKey)
    if (!segmentAttempts) attemptsBySegment.set(segmentKey, [attempt])
    else segmentAttempts.push(attempt)
  }
  let selectedPlan: PartialMeanderPlan | null = null
  for (const attemptsBySegment of attemptsByStyle.values()) {
    const segmentPitchOptions: SegmentPitchOptions[] = [
      ...attemptsBySegment.values(),
    ]
      .map((attempts) => ({
        attempts,
        maximumCapacityAttempt: attempts.reduce((bestAttempt, attempt) =>
          attempt.addedLength > bestAttempt.addedLength ? attempt : bestAttempt,
        ),
      }))
      .sort(
        (left, right) =>
          right.maximumCapacityAttempt.addedLength -
          left.maximumCapacityAttempt.addedLength,
      )
    let availableLength = 0
    for (let index = 0; index < segmentPitchOptions.length; index++) {
      availableLength +=
        segmentPitchOptions[index]!.maximumCapacityAttempt.addedLength
      if (availableLength + input.lengthTolerance < input.targetAddedLength)
        continue
      const selectedSegmentOptions = segmentPitchOptions.slice(0, index + 1)
      const capacityAttempts = selectedSegmentOptions.map(
        (options) => options.maximumCapacityAttempt,
      )
      const capacityTargets = getPlannedAttemptTargets({
        attempts: capacityAttempts,
        targetAddedLength: input.targetAddedLength,
      })
      const plannedAttempts = selectedSegmentOptions.map((options) => {
        const maximumCapacityTarget = capacityTargets.get(
          getRegressionAttemptKey(options.maximumCapacityAttempt),
        )
        if (!maximumCapacityTarget)
          throw new Error(
            `LengthMatchingSolver: missing capacity target for ${getRegressionAttemptKey(options.maximumCapacityAttempt)}`,
          )
        const feasibleAttempts = options.attempts.filter(
          (attempt) =>
            attempt.addedLength + input.lengthTolerance >=
            maximumCapacityTarget.targetAddedLength,
        )
        if (feasibleAttempts.length === 0)
          throw new Error(
            `LengthMatchingSolver: no pitch can supply planned target for route ${options.maximumCapacityAttempt.routeIndex} segment ${options.maximumCapacityAttempt.segmentIndex}`,
          )
        return feasibleAttempts.reduce((bestAttempt, attempt) =>
          attempt.qualityScore > bestAttempt.qualityScore ||
          (attempt.qualityScore === bestAttempt.qualityScore &&
            attempt.toothPitch > bestAttempt.toothPitch)
            ? attempt
            : bestAttempt,
        )
      })
      const planQualityScore = getMeanderPlanQualityScore(plannedAttempts)
      if (!selectedPlan) {
        selectedPlan = { attempts: plannedAttempts }
        break
      }
      const selectedPlanQualityScore = getMeanderPlanQualityScore(
        selectedPlan.attempts,
      )
      if (
        plannedAttempts.length < selectedPlan.attempts.length ||
        (plannedAttempts.length === selectedPlan.attempts.length &&
          planQualityScore > selectedPlanQualityScore)
      )
        selectedPlan = { attempts: plannedAttempts }
      break
    }
  }
  return selectedPlan
}

import type { RegressionAttempt } from "../internal-types"

const ADDITIONAL_SEGMENT_PENALTY = 3

/** Compare plans without allowing extra segments to inflate a summed score. */
export const getMeanderPlanQualityScore = (
  attempts: Pick<RegressionAttempt, "qualityScore">[],
): number => {
  if (attempts.length === 0)
    throw new Error("LengthMatchingSolver: cannot score an empty meander plan")
  const meanQuality =
    attempts.reduce((total, attempt) => total + attempt.qualityScore, 0) /
    attempts.length
  return meanQuality - ADDITIONAL_SEGMENT_PENALTY * (attempts.length - 1)
}

import type {
  PlannedAttemptTarget,
  RegressionAttempt,
} from "../internal-types"
import { getRegressionAttemptKey } from "./getRegressionAttemptKey"

/** Divide a target across selected attempts without exceeding their capacities. */
export const getPlannedAttemptTargets = (input: {
  attempts: RegressionAttempt[]
  targetAddedLength: number
}): Map<string, PlannedAttemptTarget> => {
  const targets = new Map<string, PlannedAttemptTarget>()
  const attempts = [...input.attempts].sort(
    (left, right) => left.addedLength - right.addedLength,
  )
  let remainingLength = input.targetAddedLength
  for (let index = 0; index < attempts.length; index++) {
    const attempt = attempts[index]!
    const target = Math.min(
      attempt.addedLength,
      remainingLength / (attempts.length - index),
    )
    targets.set(getRegressionAttemptKey(attempt), {
      routeIndex: attempt.routeIndex,
      segmentIndex: attempt.segmentIndex,
      targetAddedLength: target,
    })
    remainingLength -= target
  }
  return targets
}

